var hostContentionHourlyInHarnessShared = harnessShared.view("host_contention_hourly", {
  host: text(),
  hour: timestamp({ withTimezone: true }),
  // You can use { mode: "bigint" } if numbers are exceeding js number limitations
  intervals: bigint({ mode: "number" }),
  coveredS: numeric("covered_s"),
  cpuSomeFrac: numeric("cpu_some_frac"),
  ioSomeFrac: numeric("io_some_frac"),
  ioFullFrac: numeric("io_full_frac"),
  memorySomeFrac: numeric("memory_some_frac"),
  memoryFullFrac: numeric("memory_full_frac"),
  cgroupCores: jsonb("cgroup_cores")
}).as(sql`WITH paired AS ( SELECT s_1.host, s_1.boot_id, s_1.sampled_at, EXTRACT(epoch FROM s_1.sampled_at - lag(s_1.sampled_at) OVER w) AS dt_s, s_1.cpu_some_stall_us - lag(s_1.cpu_some_stall_us) OVER w AS cpu_some_d, s_1.io_some_stall_us - lag(s_1.io_some_stall_us) OVER w AS io_some_d, s_1.io_full_stall_us - lag(s_1.io_full_stall_us) OVER w AS io_full_d, s_1.memory_some_stall_us - lag(s_1.memory_some_stall_us) OVER w AS memory_some_d, s_1.memory_full_stall_us - lag(s_1.memory_full_stall_us) OVER w AS memory_full_d, s_1.cgroup_cpu_usage_us AS usage_cur, lag(s_1.cgroup_cpu_usage_us) OVER w AS usage_prev FROM harness_shared.host_kernel_memory_samples s_1 WINDOW w AS (PARTITION BY s_1.boot_id ORDER BY s_1.sampled_at) ), intervals AS ( SELECT paired.host, paired.boot_id, paired.sampled_at, paired.dt_s, paired.cpu_some_d, paired.io_some_d, paired.io_full_d, paired.memory_some_d, paired.memory_full_d, paired.usage_cur, paired.usage_prev, date_trunc('hour'::text, paired.sampled_at) AS hour FROM paired WHERE paired.dt_s > 0::numeric AND paired.dt_s <= 600::numeric AND (paired.cpu_some_d IS NOT NULL OR paired.io_some_d IS NOT NULL OR paired.memory_some_d IS NOT NULL OR paired.usage_cur IS NOT NULL AND paired.usage_prev IS NOT NULL) ), stall AS ( SELECT intervals.host, intervals.hour, count(*) AS intervals, sum(intervals.dt_s) AS covered_s, sum(intervals.cpu_some_d) FILTER (WHERE intervals.cpu_some_d >= 0) / NULLIF(sum(intervals.dt_s) FILTER (WHERE intervals.cpu_some_d >= 0), 0::numeric) / '1000000'::numeric AS cpu_some_frac, sum(intervals.io_some_d) FILTER (WHERE intervals.io_some_d >= 0) / NULLIF(sum(intervals.dt_s) FILTER (WHERE intervals.io_some_d >= 0), 0::numeric) / '1000000'::numeric AS io_some_frac, sum(intervals.io_full_d) FILTER (WHERE intervals.io_full_d >= 0) / NULLIF(sum(intervals.dt_s) FILTER (WHERE intervals.io_full_d >= 0), 0::numeric) / '1000000'::numeric AS io_full_frac, sum(intervals.memory_some_d) FILTER (WHERE intervals.memory_some_d >= 0) / NULLIF(sum(intervals.dt_s) FILTER (WHERE intervals.memory_some_d >= 0), 0::numeric) / '1000000'::numeric AS memory_some_frac, sum(intervals.memory_full_d) FILTER (WHERE intervals.memory_full_d >= 0) / NULLIF(sum(intervals.dt_s) FILTER (WHERE intervals.memory_full_d >= 0), 0::numeric) / '1000000'::numeric AS memory_full_frac FROM intervals GROUP BY intervals.host, intervals.hour ), cores AS ( SELECT i.host, i.hour, c.key AS cgroup, sum(c.value::numeric - ((i.usage_prev ->> c.key)::numeric)) / sum(i.dt_s) / '1000000'::numeric AS cores FROM intervals i CROSS JOIN LATERAL jsonb_each_text(i.usage_cur) c(key, value) WHERE i.usage_prev ? c.key AND c.value::numeric >= ((i.usage_prev ->> c.key)::numeric) GROUP BY i.host, i.hour, c.key ) SELECT host, hour, intervals, covered_s, cpu_some_frac, io_some_frac, io_full_frac, memory_some_frac, memory_full_frac, ( SELECT jsonb_object_agg(c.cgroup, round(c.cores, 3)) AS jsonb_object_agg FROM cores c WHERE c.host = s.host AND c.hour = s.hour) AS cgroup_cores FROM stall s`);
